 const b=button(result?.pending?tr('Checking sources…','Verificando fuentes…','Verificando fontes…'):result?.complete?tr('Review saved · no new request','Revisión guardada · sin nueva solicitud','Revisão salva · sem nova solicitação'):priorReview?tr('Review updated evidence · 1 AI request','Revisar evidencia actualizada · 1 solicitud AI','Revisar evidência atualizada · 1 solicitação AI'):tr('Ask the crew · 1 AI request','Preguntar al equipo · 1 solicitud AI','Perguntar à equipe · 1 solicitação AI'),()=>requestCrew(),'ps-primary');b.disabled=!!(result?.pending||result?.complete);crew.append(b);
